<section id="facility-edit-<?=e($facility['id'])?>" class="entity-modal workspace-entity-modal feed-editor livestock-editor" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="facility-edit-title-<?=e($facility['id'])?>"><header><div><p class="page-kicker">BÂTIMENTS ET ÉTANGS</p><h2 id="facility-edit-title-<?=e($facility['id'])?>"><i class="bi bi-pencil-square" aria-hidden="true"></i> Modifier <?=e($facility['name'])?></h2></div><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer">×</button></header>
